"""
    Build a Slack notification about a new database connection.

    """
def new_database_connection_message(payload: Any) -> object {
    connection_url = payload['connection']['url'];
    connection_name = payload['connection']['name'];
    connection_vendor = payload['connection']['vendor'];
    connection_provider = payload['connection']['provider'];
    message = 'The <{}|{}> data source was just connected.';
    message = message.format(connection_url, connection_name);
    attachments = [
        {
            'fallback': message,
            'color': 'good',
            'author_name': 'Mode',
            'author_link': 'https://modeanalytics.com/',
            'title': 'New Data Source :plus1:',
            'text': message,
            'fields': [
                {'title': 'Vendor', 'value': connection_vendor},
                {'title': 'Provider', 'value': connection_provider}
            ]
        }
    ];
    return attachments;
}

""" Generate a managed instance group resource. """
def get_managed_instance_group(
    project_id: Any,
    name: Any,
    healthcheck: Any,
    instance_template_name: Any,
    base_instance_name: Any,
    zone: Any
) -> object {
    resource = {
        'name': name,
        'type': 'gcp-types/compute-v1:instanceGroupManagers',
        'properties': {
            'project': project_id,
            'instanceTemplate': ('$(ref.' + instance_template_name + '.selfLink)'),
            'baseInstanceName': base_instance_name,
            'zone': zone,
            'targetSize': 1,
            'autoHealingPolicies': [
                {
                    'healthCheck': ('$(ref.' + healthcheck + '.selfLink)'),
                    'initialDelaySec': 120
                }
            ]
        }
    };
    return resource;
}

